    """Merge overlapping (start, end) intervals into disjoint ranges.

    Raises:
        ValueError: If any interval has start > end or is not a 2-item pair.
    """
    if not intervals:
        return []

    normalized = []
    for interval in intervals:
        try:
            start, end = interval
        except Exception as exc:
            raise ValueError("Each interval must be a (start, end) pair.") from exc

